'use strict';
const { test } = require('node:test');
const assert = require('node:assert');
const {
  generateRememberToken,
  validateRememberToken,
  revokeRememberToken,
  _rememberTokens,
} = require('../src/auth.js');

test('generated token is url-safe and high-entropy', () => {
  const token = generateRememberToken('u1');
  assert.match(token, /^[A-Za-z0-9_-]+$/);
  assert.strictEqual(token, encodeURIComponent(token));
  assert.ok(token.length >= 32, `token too short: ${token.length}`);
});

test('a valid token resolves to its user', () => {
  const token = generateRememberToken('u1');
  const record = validateRememberToken(token);
  assert.strictEqual(record.userId, 'u1');
});

test('unknown or malformed tokens are rejected', () => {
  assert.strictEqual(validateRememberToken('sess-nope'), null);
  assert.strictEqual(validateRememberToken(''), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken({}), null);
});

test('tokens are unique per call', () => {
  const seen = new Set();
  for (let i = 0; i < 100; i++) seen.add(generateRememberToken('u1'));
  assert.strictEqual(seen.size, 100);
});

test('the raw token is never stored at rest', () => {
  const token = generateRememberToken('u1');
  const atRest = JSON.stringify([..._rememberTokens.entries()]);
  assert.ok(!atRest.includes(token), 'raw token found in server-side store');
  assert.ok(
    [..._rememberTokens.keys()].every((k) => /^[a-f0-9]{64}$/.test(k)),
    'store keys are not sha256 hashes'
  );
});

test('an expired token is rejected and evicted', () => {
  const token = generateRememberToken('u1');
  const record = validateRememberToken(token);
  record.expiresAt = Date.now() - 1;
  assert.strictEqual(validateRememberToken(token), null);
  assert.strictEqual(_rememberTokens.size, [..._rememberTokens.keys()].length);
  assert.strictEqual(validateRememberToken(token), null);
});

test('a revoked token stops validating', () => {
  const token = generateRememberToken('u1');
  assert.strictEqual(revokeRememberToken(token), true);
  assert.strictEqual(validateRememberToken(token), null);
  assert.strictEqual(revokeRememberToken(token), false);
});

test('generateRememberToken requires a userId', () => {
  assert.throws(() => generateRememberToken(), /userId/);
  assert.throws(() => generateRememberToken(''), /userId/);
});

