'use strict';
// Independent QA probe for remember-me tokens. Does NOT reuse tests/remember.test.js
// assertions verbatim; re-derives checks from first principles against the live module.
const crypto = require('node:crypto');
const assert = require('node:assert');
const path = require('node:path');

const authPath = path.join(__dirname, '..', '..', '..', '..', 'src', 'auth.js');
const auth = require(authPath);
const {
  generateRememberToken,
  validateRememberToken,
  revokeRememberToken,
  _rememberTokens,
} = auth;

let failures = 0;
function check(name, fn) {
  try {
    fn();
    console.log(`PASS: ${name}`);
  } catch (e) {
    failures++;
    console.log(`FAIL: ${name} -- ${e.message}`);
  }
}

// 1. URL-safety: token must equal its own percent-encoding (no chars needing escape).
check('token is url-safe (no percent-encoding needed)', () => {
  const t = generateRememberToken('probe-user-1');
  assert.strictEqual(encodeURIComponent(t), t, 'token changed under encodeURIComponent');
  assert.ok(/^[A-Za-z0-9_-]+$/.test(t), 'token contains chars outside base64url alphabet');
});

// 2. Entropy: decode as base64url and confirm >= 256 bits (32 raw bytes) of underlying randomness.
check('token encodes >= 256 bits of raw randomness', () => {
  const t = generateRememberToken('probe-user-2');
  const raw = Buffer.from(t, 'base64url');
  assert.ok(raw.length * 8 >= 256, `only ${raw.length * 8} bits encoded`);
});

// 3. CSPRNG, not Math.random: inspect the actual function source for the call site.
check('generateRememberToken source uses crypto CSPRNG, not Math.random', () => {
  const src = generateRememberToken.toString();
  assert.ok(!/Math\.random/.test(src), 'Math.random referenced in generateRememberToken');
  assert.ok(/crypto\.(randomBytes|randomUUID|randomFillSync)/.test(src), 'no crypto CSPRNG call found');
});

// 4. Statistical sanity: 2000 tokens, no collisions, no repeated byte patterns.
check('no collisions across 2000 generated tokens (entropy sanity)', () => {
  const seen = new Set();
  for (let i = 0; i < 2000; i++) {
    const t = generateRememberToken('probe-bulk-' + i);
    assert.ok(!seen.has(t), 'collision detected');
    seen.add(t);
  }
  assert.strictEqual(seen.size, 2000);
});

// 5. At-rest storage: independently recompute sha256 of each raw token we generated
// ourselves and confirm it is the exact key used in the internal store (not just
// "looks like a hash" -- must be *the* correct hash of *that* token).
check('store key is exactly sha256(rawToken) -- independent recomputation', () => {
  const raw = generateRememberToken('probe-hash-check');
  const expectedKey = crypto.createHash('sha256').update(raw).digest('hex');
  assert.ok(_rememberTokens.has(expectedKey), 'sha256(token) not found as a store key');
  const record = _rememberTokens.get(expectedKey);
  assert.strictEqual(record.userId, 'probe-hash-check');
});

// 6. Raw token never appears anywhere in the serialized store, across many tokens.
check('raw tokens absent from full store dump (bulk)', () => {
  const raws = [];
  for (let i = 0; i < 50; i++) raws.push(generateRememberToken('probe-dump-' + i));
  const dump = JSON.stringify([..._rememberTokens.entries()]);
  for (const r of raws) {
    assert.ok(!dump.includes(r), `raw token ${r} leaked into store dump`);
  }
});

// 7. Every key in the store is a well-formed lowercase hex sha256 digest (64 chars),
// and specifically NOT equal to any raw token we've generated (defends against a
// no-op "hash" function).
check('store keys are hex-64 and never equal a raw token', () => {
  const raw = generateRememberToken('probe-notrivial');
  for (const k of _rememberTokens.keys()) {
    assert.ok(/^[a-f0-9]{64}$/.test(k), `key ${k} is not a sha256 hex digest`);
    assert.notStrictEqual(k, raw, 'store key equals a raw token (identity/no-op hash)');
  }
});

// 8. validateRememberToken never leaks the raw token back in its return value.
check('validateRememberToken return value contains no raw-token field', () => {
  const raw = generateRememberToken('probe-leak-check');
  const record = validateRememberToken(raw);
  assert.ok(record, 'expected a record for a valid token');
  const json = JSON.stringify(record);
  assert.ok(!json.includes(raw), 'validate() result leaks the raw token');
  const keys = Object.keys(record).map((k) => k.toLowerCase());
  for (const k of keys) {
    assert.ok(!k.includes('token'), `record exposes a token-shaped field: ${k}`);
  }
});

// 9. Malformed / hostile inputs all rejected (broader than the project's own test).
check('hostile/malformed inputs rejected', () => {
  const hostile = [
    'sess-nope', '', null, undefined, {}, [], 0, 1, true, false,
    '__proto__', 'constructor', NaN, Infinity,
    'a'.repeat(100000),      // huge string
    '../../etc/passwd',
    '\x00\x01\x02',
    { toString: () => 'evil' }, // object with toString should not coerce to a valid hit
  ];
  for (const h of hostile) {
    assert.strictEqual(validateRememberToken(h), null, `did not reject: ${String(h)}`);
  }
});

// 10. A single-character mutation of a valid token must NOT validate (no loose match).
check('single-char mutation of a valid token is rejected', () => {
  const raw = generateRememberToken('probe-mutate');
  const mutated = raw[0] === 'A' ? 'B' + raw.slice(1) : 'A' + raw.slice(1);
  assert.strictEqual(validateRememberToken(mutated), null, 'mutated token incorrectly validated');
});

// 11. Expiry is enforced: ttlMs=0 means immediately expired, and a short-lived token
// expires after real wall-clock time passes (not just ttlMs=0 edge case).
check('ttlMs=0 token is immediately rejected', () => {
  const raw = generateRememberToken('probe-exp-0', { ttlMs: 0 });
  assert.strictEqual(validateRememberToken(raw), null);
});

check('short-lived token expires after real elapsed time', () => {
  return new Promise((resolve, reject) => {
    const raw = generateRememberToken('probe-exp-wait', { ttlMs: 20 });
    // Immediately valid.
    const immediate = validateRememberToken(raw);
    if (!immediate || immediate.userId !== 'probe-exp-wait') {
      reject(new Error('token invalid immediately after creation'));
      return;
    }
    setTimeout(() => {
      try {
        assert.strictEqual(validateRememberToken(raw), null, 'token still valid after TTL elapsed');
        resolve();
      } catch (e) {
        reject(e);
      }
    }, 60);
  });
});

// 12. Expired tokens are evicted from the store, not just rejected (no unbounded leak).
check('expired token is evicted from the store on validate', () => {
  const raw = generateRememberToken('probe-evict', { ttlMs: 0 });
  const keyBefore = crypto.createHash('sha256').update(raw).digest('hex');
  assert.ok(_rememberTokens.has(keyBefore), 'token should exist pre-validate');
  validateRememberToken(raw);
  assert.ok(!_rememberTokens.has(keyBefore), 'expired token was not evicted after validate() call');
});

// 13. Revocation actually removes the record (checked via the store, not just via a
// second validate() call, to make sure revoke isn't a no-op that validate independently blocks).
check('revokeRememberToken removes the underlying store entry', () => {
  const raw = generateRememberToken('probe-revoke');
  const key = crypto.createHash('sha256').update(raw).digest('hex');
  assert.ok(_rememberTokens.has(key));
  const revoked = revokeRememberToken(raw);
  assert.strictEqual(revoked, true);
  assert.ok(!_rememberTokens.has(key), 'store entry still present after revoke');
});

// Async tests run via a promise-check helper; re-run the two check() calls that returned
// promises properly by awaiting them below (Node's assert throw inside setTimeout won't
// be caught by the synchronous try/catch in check(), so redo those two explicitly).
(async () => {
  // Redo #11's wait-based check with proper async handling.
  try {
    const raw = generateRememberToken('probe-exp-wait-2', { ttlMs: 20 });
    const immediate = validateRememberToken(raw);
    assert.ok(immediate && immediate.userId === 'probe-exp-wait-2');
    await new Promise((r) => setTimeout(r, 60));
    assert.strictEqual(validateRememberToken(raw), null, 'token still valid after TTL elapsed (async-confirmed)');
    console.log('PASS: short-lived token expires after real elapsed time (async-confirmed)');
  } catch (e) {
    failures++;
    console.log(`FAIL: short-lived token expires after real elapsed time (async-confirmed) -- ${e.message}`);
  }

  console.log(`\nTOTAL FAILURES: ${failures}`);
  process.exit(failures === 0 ? 0 : 1);
})();

