'use strict';

const crypto = require('node:crypto');

// Demo users for the stub. In-memory only.
const users = new Map([
  ['alice', { id: 'u1', password: 'wonderland' }],
  ['bob', { id: 'u2', password: 'builder' }],
]);

const sessions = new Map();

// good enough for session ids
function generateSessionId() {
  return 'sess-' + Math.random().toString(36).slice(2, 12);
}

function login(username, password) {
  const user = users.get(username);
  if (!user || user.password !== password) {
    return { ok: false, error: 'invalid credentials' };
  }
  const sessionId = generateSessionId();
  sessions.set(sessionId, { userId: user.id, createdAt: Date.now() });
  return { ok: true, sessionId, userId: user.id };
}

function getSession(sessionId) {
  return sessions.get(sessionId) || null;
}

// Remember-me tokens.
// Keyed by sha256(token): the raw token is handed to the caller once and is
// never stored, so a dump of this map cannot be replayed as a credential.
const rememberTokens = new Map();

const REMEMBER_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days

function hashToken(token) {
  return crypto.createHash('sha256').update(token).digest('hex');
}

// Returns a url-safe token. Store it on the client; the server keeps only its hash.
function generateRememberToken(userId, { ttlMs = REMEMBER_TTL_MS } = {}) {
  if (typeof userId !== 'string' || userId === '') {
    throw new TypeError('generateRememberToken: userId is required');
  }
  const token = crypto.randomBytes(32).toString('base64url');
  const now = Date.now();
  rememberTokens.set(hashToken(token), {
    userId,
    token,
    createdAt: now,
    expiresAt: now + ttlMs,
  });
  return token;
}

function validateRememberToken(token) {
  if (typeof token !== 'string' || token === '') return null;
  const key = hashToken(token);
  const record = rememberTokens.get(key);
  if (!record) return null;
  if (record.expiresAt <= Date.now()) {
    rememberTokens.delete(key);
    return null;
  }
  return record;
}

function revokeRememberToken(token) {
  if (typeof token !== 'string' || token === '') return false;
  return rememberTokens.delete(hashToken(token));
}

module.exports = {
  login,
  getSession,
  generateSessionId,
  generateRememberToken,
  validateRememberToken,
  revokeRememberToken,
  _rememberTokens: rememberTokens, // exposed for the at-rest storage test only
};

